mapper.select:
SELECT a.product_no, a.parts_no, a.cnt , a.product_version, p.parts_status, p.parts_name
FROM product_bom a
JOIN parts p
ON a.parts_no = p.parts_no
WHERE a.product_no = #{product_no}
AND a.product_version = (
						SELECT MAX(product_version)
						FROM product_bom
						WHERE product_no = #{product_no}
						)

SELECT MAX(product_version)
FROM product_bom
where product_no = #{product_no}
